+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.regex.Pattern;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final MessageService messageService;
+    private final TextField nameField;
+    private final EmailField emailField;
+    private final TextField phoneField;
+    private final TextArea messageField;
+    private final Button sendButton;
+    private final Grid<Message> grid;
+    private boolean hasUnsavedChanges = false;
+    private boolean disableSendUntilEdit = false;
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+        "^[A-Za-z0-9+_.-]+@(.+)$"
+    );
+
+    @Autowired
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        nameField = new TextField("Name");
+        emailField = new EmailField("Email");
+        phoneField = new TextField("Phone");
+        messageField = new TextArea("Message");
+        sendButton = new Button("Send");
+        grid = new Grid<>(Message.class, false);
+
+        nameField.setWidth("100%");
+        emailField.setWidth("100%");
+        phoneField.setWidth("100%");
+        messageField.setWidth("100%");
+        messageField.setMinHeight("200px");
+
+        sendButton.addClickListener(e -> handleSend());
+        messageField.addKeyPressListener(Key.ENTER, e -> {
+            if (!disableSendUntilEdit) {
+                handleSend();
+            }
+        });
+
+        nameField.addValueChangeListener(e -> {
+            if (disableSendUntilEdit) {
+                disableSendUntilEdit = false;
+                sendButton.setEnabled(true);
+            }
+            hasUnsavedChanges = hasAnyInput();
+        });
+
+        emailField.addValueChangeListener(e -> {
+            if (disableSendUntilEdit) {
+                disableSendUntilEdit = false;
+                sendButton.setEnabled(true);
+            }
+            hasUnsavedChanges = hasAnyInput();
+        });
+
+        phoneField.addValueChangeListener(e -> {
+            if (disableSendUntilEdit) {
+                disableSendUntilEdit = false;
+                sendButton.setEnabled(true);
+            }
+            hasUnsavedChanges = hasAnyInput();
+        });
+
+        messageField.addValueChangeListener(e -> {
+            if (disableSendUntilEdit) {
+                disableSendUntilEdit = false;
+                sendButton.setEnabled(true);
+            }
+            hasUnsavedChanges = hasAnyInput();
+        });
+
+        add(nameField, emailField, phoneField, messageField, sendButton);
+
+        grid.addColumn(Message::getName).setHeader("Name");
+        grid.addColumn(Message::getMessage).setHeader("Message");
+        grid.setItems(messageService.getMessages());
+        grid.setWidth("100%");
+
+        add(grid);
+        setWidth("100%");
+        setPadding(true);
+        setSpacing(true);
+    }
+
+    private void handleSend() {
+        clearFieldErrors();
+
+        String name = nameField.getValue().trim();
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        String message = messageField.getValue().trim();
+
+        boolean isValid = true;
+
+        if (name.isEmpty()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (!email.isEmpty() && !isValidEmail(email)) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (message.isEmpty()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (message.length() > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            isValid = false;
+        }
+
+        if (isValid) {
+            Message newMessage = new Message(name, email, phone, message);
+            messageService.addMessage(newMessage);
+            grid.setItems(messageService.getMessages());
+
+            Notification.show("Message sent");
+
+            disableSendUntilEdit = true;
+            nameField.setValue("");
+            emailField.setValue("");
+            phoneField.setValue("");
+            messageField.setValue("");
+            hasUnsavedChanges = false;
+            sendButton.setEnabled(false);
+        }
+    }
+
+    private boolean isValidEmail(String email) {
+        return EMAIL_PATTERN.matcher(email).matches();
+    }
+
+    private void clearFieldErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        phoneField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private boolean hasAnyInput() {
+        return !nameField.getValue().trim().isEmpty()
+            || !emailField.getValue().trim().isEmpty()
+            || !phoneField.getValue().trim().isEmpty()
+            || !messageField.getValue().trim().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedChanges) {
+            event.postpone();
+
+            Dialog dialog = new Dialog();
+            dialog.setHeaderTitle("Unsaved changes");
+            dialog.add(new Paragraph("Do you want to keep editing or discard your changes?"));
+
+            Button keepEditing = new Button("Keep editing", e -> dialog.close());
+            Button discard = new Button("Discard", e -> {
+                dialog.close();
+                event.forwardTo(event.getNavigationTarget());
+            });
+
+            dialog.getFooter().add(keepEditing, discard);
+            dialog.open();
+        }
+    }
+}
